static void sndEngineStop(void){}
static void sndAllStop(void){}
static void sndEngine(const Car *p,int on,int gas){ (void)p;(void)on;(void)gas; }
static void sndHit(float dmg,float x,float z){ (void)dmg;(void)x;(void)z; }
static void sndVoice(int kind){ (void)kind; }
static void sndWreck(float x,float z,int isPlayer){ (void)x;(void)z;(void)isPlayer; }
static void sndUi(int kind){ (void)kind; }
static void sndDrive(const Car *p,int active){ (void)p;(void)active; }
static void sndTick(void){}
static void musInit(void){}
static void musStop(void){}
static void musUpdate(void){}
static void musPlayMenu(void){}
static void musPlayRace(void){}
static void musMenu(void){}
static void sndGameStop(void){}
static void banUpdate(void){}
static void banRelease(void){}
#endif

